// The 卡丁城 fuel tank table (server-go/internal/data/economy/kart-tanks.json,
// generated by tools/export-kart-tanks.mjs): its formula holds for every row,
// capacity grows with the model's box volume, every shop kart and system kart
// is listed, and (with mirror/p3553 present) the committed file is current.
//
//   node --import tsx --test tests/kart-tanks.test.mjs
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

const clientDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const projectRoot = path.resolve(clientDir, "..");
const economyDir = path.join(projectRoot, "server-go/internal/data/economy");
const table = JSON.parse(readFileSync(path.join(economyDir, "kart-tanks.json"), "utf8"));
const catalogKarts = JSON.parse(readFileSync(path.join(economyDir, "catalog.json"), "utf8")).items
  .filter(item => item.kind === "kart");
const rows = [...table.karts, ...table.system];
const volume = row => row.length * row.width * row.height;

// The formula the tool documents, restated independently.
const capacityFor = v => Math.min(100, Math.max(20, Math.round(40 * (v / table.medianVolume) ** 0.6)));
const sizeClassFor = capacity => capacity < 30 ? "small" : capacity < 45 ? "medium" : capacity < 65 ? "large" : "huge";

test("every row follows the documented formula", () => {
  assert.equal(table.version, 1);
  assert.match(table.formula, /round\(40 × \(V \/ Vmed\)\^0\.6\), 20, 100\)/);
  const measured = table.karts.filter(row => row.measured).map(volume).sort((a, b) => a - b);
  const middle = measured.length >> 1;
  const median = measured.length % 2 ? measured[middle] : (measured[middle - 1] + measured[middle]) / 2;
  assert.equal(table.medianVolume, Math.round(median * 1e4) / 1e4);
  for (const row of rows) {
    const where = `${row.itemId ?? row.key} ${row.internalId}`;
    for (const axis of ["length", "width", "height"]) {
      assert.ok(row[axis] > 0 && row[axis] < 10, `${where} ${axis} ${row[axis]}`);
      assert.equal(row[axis], Math.round(row[axis] * 1000) / 1000, `${where} ${axis} has 3 decimals`);
    }
    assert.equal(row.volume, Math.round(volume(row) * 1000) / 1000, `${where} volume`);
    assert.equal(row.capacity, capacityFor(volume(row)), `${where} capacity`);
    assert.equal(row.sizeClass, sizeClassFor(row.capacity), `${where} sizeClass`);
    assert.equal(typeof row.measured, "boolean", `${where} measured`);
  }
});

test("capacity never shrinks as the box volume grows", () => {
  const sorted = [...rows].sort((a, b) => volume(a) - volume(b));
  for (let i = 1; i < sorted.length; i++)
    assert.ok(sorted[i].capacity >= sorted[i - 1].capacity,
      `${sorted[i].internalId} (${volume(sorted[i])}) < ${sorted[i - 1].internalId} (${volume(sorted[i - 1])})`);
  const classes = ["small", "medium", "large", "huge"];
  for (let i = 1; i < sorted.length; i++)
    assert.ok(classes.indexOf(sorted[i].sizeClass) >= classes.indexOf(sorted[i - 1].sizeClass));
});

test("every catalog kart and system kart is listed once, sorted by itemId", () => {
  assert.deepEqual(table.karts.map(row => row.itemId), catalogKarts.map(item => item.itemId).sort((a, b) => a - b));
  const byItem = new Map(catalogKarts.map(item => [item.itemId, item]));
  for (const row of table.karts) {
    assert.equal(row.internalId, byItem.get(row.itemId).internalId);
    assert.equal(row.name, byItem.get(row.itemId).name);
    assert.equal(row.key, undefined);
  }
  // System karts: equipment itemIds["3"] === 0, named by systemKart.
  assert.deepEqual(table.system.map(row => row.key),
    ["legacyPractice", "legacyPracticeBlackline", "legacyPracticeX", "practiceKart"]);
  for (const row of table.system) assert.equal(row.itemId, undefined);
  const starter = JSON.parse(readFileSync(path.join(economyDir, "catalog.json"), "utf8")).starter.kart;
  assert.equal(table.system.find(row => row.key === starter.systemKey)?.internalId, starter.internalId);
});

test("known karts land in the expected classes", () => {
  const kart = itemId => table.karts.find(row => row.itemId === itemId);
  assert.equal(kart(524).sizeClass, "small", "超迷你踏板车 Z7");
  assert.equal(kart(3).sizeClass, "medium", "爆烈 G3");
  assert.equal(kart(640).sizeClass, "large", "挖掘机 HT");
  assert.equal(kart(571).sizeClass, "large", "胖墩坦克车 Z7+");
  assert.equal(kart(837).sizeClass, "huge", "擎天柱");
  assert.equal(kart(910).capacity, 100, "小苹果 9");
  assert.ok(kart(1593).capacity > kart(1).capacity * 2, "雪人 迅 vs 爆烈 C1");
});

const mirror = path.join(projectRoot, "mirror");
const haveMirror = existsSync(path.join(mirror, "__p3553/resources")) &&
  existsSync(path.join(mirror, "__p3553/archive-index")) &&
  existsSync(path.join(mirror, "p3553")) && readdirSync(path.join(mirror, "p3553")).length > 0;

test("kart-tanks.json is current with mirror/p3553", { skip: !haveMirror, timeout: 300_000 }, () => {
  execFileSync(process.execPath, ["--import", "tsx", "tools/export-kart-tanks.mjs", "--check"],
    { cwd: clientDir, stdio: "pipe" });
});
